<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('recruiter');$user=current_user();$flashes=render_flashes();$currentPage='candidate_view';$pageTitle='Candidate Profile';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$uid=(int)($user['id']??$user['user_id']??0);$cid=(int)($_GET['id']??0);if($uid<=0||$cid<=0){http_response_code(400);exit('Invalid request.');}$s=$conn->prepare("SELECT cp.*,u.first_name,u.last_name,u.email,cc.granted_at,cc.expires_at FROM candidate_profiles cp JOIN users u ON u.id=cp.user_id JOIN candidate_consents cc ON cc.candidate_id=cp.user_id AND cc.consent_type='recruiter_discovery' AND cc.status='consented' AND (cc.expires_at IS NULL OR cc.expires_at>NOW()) WHERE cp.user_id=? LIMIT 1");$s->bind_param('i',$cid);$s->execute();$c=$s->get_result()->fetch_assoc();$s->close();if(!$c){http_response_code(403);exit('Candidate not found or recruiter consent is not valid.');}$skills=[];$s=$conn->prepare("SELECT s.name,s.category,s.is_scarce,cs.proficiency_level,cs.years_experience,cs.verification_status,cs.verified_at,cs.evidence_summary FROM candidate_skills cs JOIN skills s ON s.id=cs.skill_id WHERE cs.candidate_id=? ORDER BY s.is_scarce DESC,cs.verification_status='verified' DESC,s.name");$s->bind_param('i',$cid);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$skills[]=$x;$s->close();$f=trim((string)$c['first_name']);$l=trim((string)$c['last_name']);$name=trim($f.' '.$l)?:'Candidate';rc_activity($conn,$uid,'candidate_profile_viewed','Viewed a recruiter-consented candidate profile.','candidate',$cid);require __DIR__.'/_layout_start.php';?>
<div class="rc-profile-hero"><div class="rc-avatar rc-avatar--xl"><?=e(rc_initials($f,$l))?></div><div class="rc-profile-copy"><span class="rc-eyebrow">Verified Talent Profile</span><h2><?=e($name)?></h2><p><?=e((string)($c['headline']?:'Candidate'))?></p><div class="rc-chips"><b><?=e(trim((string)$c['city'].', '.(string)$c['province'],' ,'))?></b><b>Consent valid</b></div></div><a class="rc-btn rc-btn--primary" href="<?=url('recruiter/shortlists.php?candidate_id='.$cid)?>"><i class="fas fa-plus"></i> Add to Shortlist</a></div>
<div class="rc-grid-2"><section class="rc-card"><div class="rc-card__header"><h3>Profile Summary</h3></div><div class="rc-card__body rc-details"><div><span>Experience</span><strong><?=number_format((int)$c['years_experience'])?> years</strong></div><div><span>Availability</span><strong><?=e(rc_label($c['availability_status']))?></strong></div><div><span>Profile Verification</span><strong><?=e(rc_label($c['verification_status']))?></strong></div><div><span>Last Verified</span><strong><?=e(rc_datetime($c['last_verified_at']))?></strong></div><div><span>Consent Granted</span><strong><?=e(rc_datetime($c['granted_at']))?></strong></div><div><span>Consent Expires</span><strong><?=e(rc_datetime($c['expires_at'],'No expiry'))?></strong></div></div></section><section class="rc-card"><div class="rc-card__header"><h3>Trust Signals</h3></div><div class="rc-card__body"><div class="rc-trust"><div><i class="fas fa-badge-check"></i><div><strong>Verified Profile</strong><span>Current profile verification available.</span></div></div><div><i class="fas fa-user-shield"></i><div><strong>Consent Valid</strong><span>Recruiter-discovery consent checked at access time.</span></div></div><div><i class="fas fa-fingerprint"></i><div><strong>Audited Access</strong><span>Profile access recorded in activity log.</span></div></div></div></div></section></div>
<section class="rc-card"><div class="rc-card__header"><h3>Skills & Evidence</h3></div><?php if(!$skills):?><div class="rc-empty"><i class="fas fa-code"></i><strong>No skills recorded</strong></div><?php else:?><div class="rc-skill-list"><?php foreach($skills as $sk):?><article><div><strong><?=e($sk['name'])?></strong><span><?=e((string)($sk['category']?:'General'))?><?=$sk['is_scarce']?' · Scarce skill':''?></span></div><div><span>Proficiency</span><strong><?=e(rc_label($sk['proficiency_level']))?></strong></div><div><span>Experience</span><strong><?=number_format((int)$sk['years_experience'])?> years</strong></div><div><span>Verification</span><strong><?=e(rc_label($sk['verification_status']))?></strong></div><div><span>Recency</span><strong><?=e(rc_date($sk['verified_at']))?></strong></div><div><span>Evidence</span><strong><?=e((string)($sk['evidence_summary']?:'No evidence summary'))?></strong></div></article><?php endforeach;?></div><?php endif;?></section>
<?php require __DIR__.'/_layout_end.php';?>